#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto apply=[&](int x,int y){
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
        ops.push_back({x,y});
    };
    // Place elements 1..n one by one
    for(int i=0;i<n-1;i++){
        int pos=-1;
        for(int j=0;j<n;j++) if(p[j]==i+1){pos=j;break;}
        if(pos==i) continue;
        // Step 1: bring element to position 0
        if(pos>0){
            if(pos>1){
                apply(1, n-pos); // element at pos -> position 0
            } else { // pos==1
                if(n>3) apply(1, n-3); // some shuffle, then retry
                else apply(1,1); // n==3: op(1,1)
                for(int j=0;j<n;j++) if(p[j]==i+1){pos=j;break;}
                if(pos>1) apply(1, n-pos);
                else if(pos>0 && pos==1 && n>2) { apply(2, n-3>0?n-3:1); for(int j=0;j<n;j++) if(p[j]==i+1){pos=j;break;} if(pos>1) apply(1,n-pos); }
            }
            for(int j=0;j<n;j++) if(p[j]==i+1){pos=j;break;}
            if(pos!=0) continue; // fallback, shouldn't happen ideally
        }
        // Step 2: move from position 0 to position i
        if(i==0) continue;
        if(i>=2){
            apply(n-i, i-1); // element at 0 -> position i
        } else { // i==1
            // op(n-1,y): y>0, n-1+y<n -> y<1, impossible
            // Use: op(n-2,1): elem at 0 -> pos 2, then op(1,n-2): elem at 2->0? No.
            apply(n-2, 1); // elem 0->pos 2
            apply(1, n-2); // elem at pos 2 -> pos 0... 
            // Actually elem at 2: with op(1, n-2), new pos = 2-1=1. Yes!
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
